def _seed_motivations() -> None:
    import json
    import uuid
    from datetime import datetime, timedelta, timezone

    from app.services.motivations_seed import MOTIVATIONS

    bind = op.get_bind()
    base = datetime.now(timezone.utc)
    for i, m in enumerate(MOTIVATIONS):
        bind.execute(
            sa.text(
                "INSERT INTO motivations (id, text, category, is_active, created_at, updated_at)"
                " VALUES (:id, CAST(:text AS jsonb), CAST(:category AS motivation_category), true, :ts, :ts)"
            ),
            # Tartib saqlanishi uchun vaqtlar ketma-ket
            {"id": uuid.uuid4(), "text": json.dumps(m["text"], ensure_ascii=False),
             "category": m["category"], "ts": base + timedelta(seconds=i)},
        )


